1	import React, { useState } from 'react';
2	import { IntlProvider } from 'react-intl';
3	import { describe, test, expect, vi } from 'vitest';
4	import { render, screen, within } from '@testing-library/react';
5	import userEvent from '@testing-library/user-event';
6	import ColourSwatches from './index';
7	import type { ColourVariant } from './index';
8	
9	// The icons barrel (overrides/app/components/icons/index.tsx) re-exports the SFCC icons barrel,
10	// which has a top-level side effect that fails under Vitest (SVG imports resolve to path strings,
11	// not components). Mock it at the barrel level per testing.md > "Known gap: ZimmIcon throws under Vitest".
12	vi.mock('../../../icons', () => ({
13	  ChevronLeftIcon: () => null,
14	  ChevronRightIcon: () => null,
15	}));
16	
17	/*
18	 * Deliberately NOT a re-test of what the Storybook `play` functions already cover (click moves
19	 * selection, label follows). Per .claude/rules/testing.md, coverage is not duplicated across
20	 * layers — this file targets the logic edges a story cannot cheaply enumerate:
21	 *
22	 *   - the `currentIndex === -1` backward case, where plain modulo silently lands on the
23	 *     second-to-last swatch instead of the last (the component carries a comment warning
24	 *     about exactly this — it is the kind of bug that survives a refactor invisibly)
25	 *   - wrap boundaries in both directions
26	 *   - the DIS query-string separator, which must be `&` when the resolved link already has `?`
27	 *   - the roving-tabIndex invariant: exactly one tab stop, always
28	 *
29	 * It is also the only layer that runs locally: `test-storybook` currently fails on every story
30	 * in the repo (pre-existing `StorybookTestRunnerError` env fault), so the `play` functions are
31	 * unverified until CI. These tests are not blocked on that.
32	 */
33	
34	const IMG = 'https://example.test/swatch.jpg';
35	
36	const variant = (value: string, name: string, over: Partial<ColourVariant> = {}): ColourVariant => ({
37	  value,
38	  name,
39	  imageUrl: IMG,
40	  orderable: true,
41	  ...over,
42	});
43	
44	/** The component is controlled, so keyboard/click flows need state to move against. */
45	const Harness = ({ variants, initial }: { variants: readonly ColourVariant[]; initial?: string }) => {
46	  const [selected, setSelected] = useState<string | undefined>(initial);
47	  return (
48	    <IntlProvider locale="en" defaultLocale="en">
49	      <ColourSwatches variants={variants} selectedValue={selected} onSelect={setSelected} />
50	    </IntlProvider>
51	  );
52	};
53	
54	const THREE = [variant('a', 'Alpha'), variant('b', 'Bravo'), variant('c', 'Charlie')];
55	const FIVE = [
56	  variant('a', 'Alpha'),
57	  variant('b', 'Bravo'),
58	  variant('c', 'Charlie'),
59	  variant('d', 'Delta'),
60	  variant('e', 'Echo'),
61	];
62	
63	const radios = () => screen.getAllByRole('radio');
64	const group = () => screen.getByRole('radiogroup', { name: 'Colour' });
65	
66	describe('ColourSwatches — AC5 filter', () => {
67	  test('withholds a colour with no swatch image', () => {
68	    render(<Harness variants={[...THREE, variant('d', 'Delta', { imageUrl: undefined })]} initial="a" />);
69	
70	    expect(radios()).toHaveLength(3);
71	    expect(screen.queryByRole('radio', { name: 'Delta' })).not.toBeInTheDocument();
72	  });
73	
74	  test('withholds a colour that is not orderable even when it has a good image', () => {
75	    // The load-bearing half: an unorderable colour with a perfectly valid image must still
76	    // be absent. A filter on imageUrl alone would let this one through.
77	    render(<Harness variants={[...THREE, variant('d', 'Delta', { orderable: false })]} initial="a" />);
78	
79	    expect(radios()).toHaveLength(3);
80	    expect(screen.queryByRole('radio', { name: 'Delta' })).not.toBeInTheDocument();
81	  });
82	
83	  test('renders nothing selectable when every colour is withheld', () => {
84	    render(
85	      <Harness
86	        variants={[variant('a', 'Alpha', { orderable: false }), variant('b', 'Bravo', { imageUrl: undefined })]}
87	      />,
88	    );
89	
90	    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
91	    expect(screen.queryAllByRole('radio')).toHaveLength(0);
92	  });
93	});
94	
95	describe('ColourSwatches — AC1 single offered colour', () => {
96	  test('shows the label and colour name but no swatch row', () => {
97	    render(<Harness variants={[variant('a', 'Alpha')]} />);
98	
99	    expect(screen.getByText('Colour:')).toBeInTheDocument();
100	    expect(screen.getByTestId('pdp-colour-selected-name')).toHaveTextContent('Alpha');
101	    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
102	  });
103	
104	  test('names the sole *offered* colour, not the sole recorded one', () => {
105	    // Two colours recorded, one withheld — from the shopper's side this is a single-colour
106	    // product, so the label must still name the surviving colour with nothing selected.
107	    render(<Harness variants={[variant('a', 'Alpha'), variant('b', 'Bravo', { orderable: false })]} />);
108	
109	    expect(screen.getByTestId('pdp-colour-selected-name')).toHaveTextContent('Alpha');
110	    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
111	  });
112	});
113	
114	describe('ColourSwatches — keyboard navigation', () => {
115	  test('ArrowLeft from the default tab stop (nothing selected) lands on the LAST swatch', async () => {
116	    // When nothing is selected, Tab lands on Alpha (the default tab stop, index 0).
117	    // ArrowLeft from Alpha wraps back to Charlie — the last swatch — via (0 - 1 + 3) % 3 = 2.
118	    // This also guards the old modulo trap: before the focused-element fix, currentIndex was
119	    // derived from selectedValue (-1 when nothing selected), which computed (len - 2) = Bravo.
120	    const user = userEvent.setup();
121	    render(<Harness variants={THREE} />);
122	
123	    await user.keyboard('{Tab}');
124	    await user.keyboard('{ArrowLeft}');
125	
126	    expect(screen.getByRole('radio', { name: 'Charlie' })).toHaveAttribute('aria-checked', 'true');
127	  });
128	
129	  test('ArrowRight from the default tab stop (nothing selected) moves to the second swatch', async () => {
130	    // When nothing is selected, Tab lands on Alpha (index 0). ArrowRight moves forward to
131	    // Bravo (index 1) — navigation is relative to the focused swatch, not the selected one.
132	    const user = userEvent.setup();
133	    render(<Harness variants={THREE} />);
134	
135	    await user.keyboard('{Tab}');
136	    await user.keyboard('{ArrowRight}');
137	
138	    expect(screen.getByRole('radio', { name: 'Bravo' })).toHaveAttribute('aria-checked', 'true');
139	  });
140	
141	  test('wraps forward from the last swatch to the first', async () => {
142	    const user = userEvent.setup();
143	    render(<Harness variants={THREE} initial="c" />);
144	
145	    await user.keyboard('{Tab}');
146	    await user.keyboard('{ArrowRight}');
147	
148	    expect(screen.getByRole('radio', { name: 'Alpha' })).toHaveAttribute('aria-checked', 'true');
149	  });
150	
151	  test('wraps backward from the first swatch to the last', async () => {
152	    const user = userEvent.setup();
153	    render(<Harness variants={THREE} initial="a" />);
154	
155	    await user.keyboard('{Tab}');
156	    await user.keyboard('{ArrowLeft}');
157	
158	    expect(screen.getByRole('radio', { name: 'Charlie' })).toHaveAttribute('aria-checked', 'true');
159	  });
160	
161	  test('ArrowDown and ArrowUp mirror ArrowRight and ArrowLeft', async () => {
162	    const user = userEvent.setup();
163	    render(<Harness variants={THREE} initial="a" />);
164	
165	    await user.keyboard('{Tab}');
166	    await user.keyboard('{ArrowDown}');
167	    expect(screen.getByRole('radio', { name: 'Bravo' })).toHaveAttribute('aria-checked', 'true');
168	
169	    await user.keyboard('{ArrowUp}');
170	    expect(screen.getByRole('radio', { name: 'Alpha' })).toHaveAttribute('aria-checked', 'true');
171	  });
172	
173	  test('navigation skips over withheld colours because they never render', async () => {
174	    // 'Bravo' is unorderable, so ArrowRight from 'Alpha' must reach 'Charlie' directly.
175	    const user = userEvent.setup();
176	    render(
177	      <Harness
178	        variants={[variant('a', 'Alpha'), variant('b', 'Bravo', { orderable: false }), variant('c', 'Charlie')]}
179	        initial="a"
180	      />,
181	    );
182	
183	    await user.keyboard('{Tab}');
184	    await user.keyboard('{ArrowRight}');
185	
186	    expect(screen.getByRole('radio', { name: 'Charlie' })).toHaveAttribute('aria-checked', 'true');
187	  });
188	
189	  test('does not move the selection on keys that are neither arrows nor activation', async () => {
190	    const onSelect = vi.fn();
191	    const user = userEvent.setup();
192	    render(
193	      <IntlProvider locale="en" defaultLocale="en">
194	        <ColourSwatches variants={THREE} selectedValue="a" onSelect={onSelect} />
195	      </IntlProvider>,
196	    );
197	
198	    await user.keyboard('{Tab}');
199	    await user.keyboard('x');
200	    await user.keyboard('{Escape}');
201	    await user.keyboard('{Home}');
202	
