//
// Purpose: does the seed-on-mount + sync-effect pattern actually recover from a
// prop (urlColour) changing on a re-render WITHOUT an unmount — the classic
// useState(derivedFromProp) trap?
const Harness = ({ urlColour, requestedProductId }: { urlColour?: string; requestedProductId: string }) => {
  const [shopperSelectedColour, setShopperSelectedColour] = useState<string | undefined>(urlColour);

  useEffect(() => {
    setShopperSelectedColour(urlColour);
    // mirrors the real file's exhaustive-deps suppression
  }, [urlColour, requestedProductId]);

  return <div data-testid="value">{shopperSelectedColour ?? '(none)'}</div>;
};

describe('AUDIT PROBE — shopperSelectedColour seed-on-mount pattern', () => {
